require_once __DIR__ . '/db.php';
$user=require_login();$admin=is_admin($user);$pdo=db();$error='';$dbError='';$ok='';$sectors=['engenharia'=>'Engenharia','administrativo'=>'Administrativo','obras'=>'Obras'];
if($_SERVER['REQUEST_METHOD']==='POST'){
