 else{$action=$_POST['action']??'';
  if(in_array($action,['create_meta','update_meta'],true)){
   if(!$admin){http_response_code(403);exit('Somente administradoras podem criar ou alterar metas.');}
   if($action==='create_meta'){$title=trim($_POST['titulo']??'');$sector=$user['setor'];$start=$_POST['semana_inicio']??'';$end=$_POST['semana_fim']??'';if($title===''||!isset($sectors[$sector])||!$start||!$end||$end<$start)$error='Preencha título e período válido.';else{$stmt=$pdo->prepare('INSERT INTO metas(titulo,descricao,setor,semana_inicio,semana_fim,criada_por) VALUES(?,?,?,?,?,?)');$stmt->execute([$title,trim($_POST['descricao']??'')?:null,$sector,$start,$end,$user['id']]);header('Location: '.app_path('painel.html?salvo=meta'));exit;}}
   else{$id=(int)($_POST['meta_id']??0);$progress=filter_var($_POST['progresso']??null,FILTER_VALIDATE_FLOAT);if($id<1||$progress===false||$progress<0||$progress>100)$error='O progresso deve ficar entre 0 e 100.';else{$check=$pdo->prepare('SELECT id FROM metas WHERE id=? AND setor=?');$check->execute([$id,$user['setor']]);if(!$check->fetch())$error='Meta não encontrada no seu setor.';else{$stmt=$pdo->prepare('UPDATE metas SET progresso_percentual=?,status=? WHERE id=? AND setor=?');$stmt->execute([$progress,$progress>=100?'concluida':($progress>0?'em_andamento':'a_fazer'),$id,$user['setor']]);$stmt=$pdo->prepare('INSERT INTO meta_atualizacoes(meta_id,usuario_id,progresso_percentual,comentario) VALUES(?,?,?,?)');$stmt->execute([$id,$user['id'],$progress,trim($_POST['comentario']??'')?:null]);header('Location: '.app_path('painel.html?salvo=atualizacao'));exit;}}}
  }elseif($action==='checklist'){
   if($admin){http_response_code(403);exit('O checklist individual é para usuárias comuns.');}$id=(int)($_POST['meta_id']??0);$done=isset($_POST['concluida'])?1:0;$stmt=$pdo->prepare('SELECT id FROM metas WHERE id=? AND setor=?');$stmt->execute([$id,$user['setor']]);if(!$stmt->fetch())$error='Meta não encontrada no seu setor.';else{$stmt=$pdo->prepare('INSERT INTO meta_checklist(meta_id,usuario_id,concluida) VALUES(?,?,?) ON CONFLICT (meta_id,usuario_id) DO UPDATE SET concluida=EXCLUDED.concluida,atualizado_em=now()');$stmt->execute([$id,$user['id'],$done]);header('Location: '.app_path('painel.html?salvo=checklist'));exit;}
  }elseif($action==='user_status'){http_response_code(403);exit('Somente administradoras podem alterar o status da meta.');}
  else $error='Ação inválida.';
 }
