if(isset($_GET['salvo']))$ok=['meta'=>'Meta adicionada.','atualizacao'=>'Atualização salva.','checklist'=>'Checklist atualizado.'][$_GET['salvo']]??'';
try{if($admin){$stmt=$pdo->prepare('SELECT m.*,0 AS checklist_concluida FROM metas m WHERE m.setor=? ORDER BY m.semana_inicio,m.id');$stmt->execute([$user['setor']]);$metas=$stmt->fetchAll();}else{$stmt=$pdo->prepare('SELECT m.*,COALESCE(c.concluida,0) AS checklist_concluida FROM metas m LEFT JOIN meta_checklist c ON c.meta_id=m.id AND c.usuario_id=? WHERE m.setor=? ORDER BY m.semana_inicio,m.id');$stmt->execute([$user['id'],$user['setor']]);$metas=$stmt->fetchAll();}}catch(Throwable $e){$metas=[];$dbError='O painel não conseguiu carregar as metas. Importe o arquivo database.sql no MySQL do XAMPP e confirme se o banco ellenco_gestao contém as tabelas metas e meta_checklist.';}
