function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}function dbr(string $v):string{return date('d/m/Y',strtotime($v));}
function goal_card_compact(array $m,bool $admin):string{
 $status=['a_fazer'=>'A fazer','em_andamento'=>'Em andamento','concluida'=>'Concluída'][$m['status']]??$m['status'];
 $progress=max(0,min(100,(float)$m['progresso_percentual']));
 $isOverdue=$m['semana_fim']<date('Y-m-d')&&$m['status']!=='concluida';
 $cardTone=$isOverdue?'border-red-300 bg-red-50 hover:border-red-400':'border-gray-200 bg-gray-50 hover:border-blue-200';
 $html='<details class="group rounded-xl border '.$cardTone.' p-3 transition">';
 $html.='<summary class="flex cursor-pointer list-none items-center justify-between gap-3 [&::-webkit-details-marker]:hidden"><span class="min-w-0"><span class="block truncate text-sm font-semibold text-slate-800">'.h($m['titulo']).'</span><span class="mt-1 block text-[11px] text-slate-500">'.h(sector_label($m['setor'])).' · '.dbr($m['semana_inicio']).'–'.dbr($m['semana_fim']).'</span></span><span aria-hidden="true" class="shrink-0 text-sm text-slate-400 transition group-open:rotate-180">⌄</span></summary>';
 $html.='<div class="mt-3 space-y-3 border-t border-gray-200 pt-3"><span class="inline-flex rounded-full bg-white px-2.5 py-1 text-[11px] font-semibold text-slate-600">'.h($status).'</span>';
 if(trim((string)$m['descricao'])!=='')$html.='<p class="text-xs leading-relaxed text-slate-600">'.h($m['descricao']).'</p>';
 if($admin)$html.='<form method="post" class="space-y-2"><input type="hidden" name="csrf_token" value="'.h(csrf_token()).'"><input type="hidden" name="action" value="update_meta"><input type="hidden" name="meta_id" value="'.(int)$m['id'].'"><div class="grid grid-cols-1 gap-2 sm:grid-cols-[100px_1fr]"><label class="text-[11px] font-medium text-slate-600">Progresso %<input type="number" min="0" max="100" name="progresso" value="'.$progress.'" class="mt-1 w-full rounded-lg border border-gray-200 bg-white p-2 text-sm"></label><label class="text-[11px] font-medium text-slate-600">Atualização<input name="comentario" maxlength="1000" placeholder="Descreva a atualização" class="mt-1 w-full rounded-lg border border-gray-200 bg-white p-2 text-sm"></label></div><button class="w-full rounded-lg bg-blue-800 px-3 py-2 text-xs font-semibold text-white hover:bg-blue-900">Salvar atualização</button></form>';
 else{$html.='<div><div class="mb-1 flex justify-between text-[11px] text-slate-600"><span>Progresso</span><span>'.$progress.'%</span></div><div class="h-2 overflow-hidden rounded-full bg-slate-200"><div class="h-full rounded-full bg-blue-700" style="width:'.$progress.'%"></div></div></div><form method="post"><input type="hidden" name="csrf_token" value="'.h(csrf_token()).'"><input type="hidden" name="action" value="checklist"><input type="hidden" name="meta_id" value="'.(int)$m['id'].'"><label class="flex items-center gap-2 text-xs text-slate-600"><input type="checkbox" name="concluida" value="1" '.($m['checklist_concluida']?'checked':'').' onchange="this.form.submit()"><span>'.($m['checklist_concluida']?'Minha tarefa concluída':'Marcar meu checklist').'</span></label></form>';}
 return $html.'</div></details>';
}
function goal_card(array $m,bool $admin):string{$status=['a_fazer'=>'A fazer','em_andamento'=>'Em andamento','concluida'=>'Concluída'][$m['status']]??$m['status'];$html='<article class="bg-gray-50 border rounded-lg p-3"><div class="flex justify-between gap-2"><div><h4 class="font-semibold text-sm">'.h($m['titulo']).'</h4><p class="text-[11px] text-gray-500">'.h(sector_label($m['setor'])).' · '.dbr($m['semana_inicio']).'–'.dbr($m['semana_fim']).'</p></div><span class="text-xs font-semibold">'.h($status).'</span></div>'.($m['descricao']?'<p class="text-xs text-gray-600 mt-2">'.h($m['descricao']).'</p>':'');if($admin)$html.='<form method="post" class="mt-3 space-y-2"><input type="hidden" name="csrf_token" value="'.h(csrf_token()).'"><input type="hidden" name="action" value="update_meta"><input type="hidden" name="meta_id" value="'.(int)$m['id'].'"><div class="flex gap-2"><label class="text-[11px] flex-1">Progresso %<input type="number" min="0" max="100" name="progresso" value="'.(float)$m['progresso_percentual'].'" class="mt-1 w-full border rounded p-1.5"></label><label class="text-[11px] flex-[2]">Atualização<input name="comentario" maxlength="1000" class="mt-1 w-full border rounded p-1.5"></label></div><button class="w-full bg-blue-800 text-white rounded px-3 py-1.5 text-xs">Salvar atualização</button></form>';else$html.='<form method="post" class="mt-3"><input type="hidden" name="csrf_token" value="'.h(csrf_token()).'"><input type="hidden" name="action" value="checklist"><input type="hidden" name="meta_id" value="'.(int)$m['id'].'"><label class="flex items-center gap-2 text-xs"><input type="checkbox" name="concluida" value="1" '.($m['checklist_concluida']?'checked':'').' onchange="this.form.submit()"><span>'.($m['checklist_concluida']?'Minha tarefa concluída':'Marcar meu checklist').'</span></label></form>';$html.='</article>';return $html;}
$html=file_get_contents(__DIR__.'/../painel.html');$html=str_replace('Usuário 1',h($user['nome']),$html);$html=str_replace('Administradora',$admin?'Administradora':'Usuário',$html);
if($admin)$html=preg_replace_callback('~<a\b[^>]*>.*?</a>~si',function($m){if(stripos($m[0],'Nova Meta')!==false||stripos($m[0],'Adicionar nova meta')!==false)return str_replace('href="#"','href="#gerenciar-metas"',$m[0]);return$m[0];},$html);else$html=preg_replace_callback('~<a\b[^>]*>.*?</a>~si',function($m){return(stripos($m[0],'Nova Meta')!==false||stripos($m[0],'Adicionar nova meta')!==false)?'':$m[0];},$html);
$summaryCounts=[$counts['total'],$counts['em_andamento'],$counts['concluida'],$counts['atrasada']];$sumStart=strpos($html,'<!-- RESUMO DAS METAS -->');$boardStart=strpos($html,'<!-- QUADRO KANBAN -->');if($sumStart!==false&&$boardStart!==false){$summary=substr($html,$sumStart,$boardStart-$sumStart);$i=0;$summary=preg_replace_callback('~(<h2 class="text-3xl font-bold[^"]*">)0(</h2>)~',function($m)use(&$i,$summaryCounts){$n=$summaryCounts[$i]??0;$i++;return$m[1].$n.$m[2];},$summary,4);$html=substr_replace($html,$summary,$sumStart,$boardStart-$sumStart);}
$board='<div id="quadro-metas" class="grid grid-cols-1 lg:grid-cols-3 gap-5">';$names=['a_fazer'=>'A Fazer','em_andamento'=>'Em Andamento','concluida'=>'Concluídas'];$badges=['a_fazer'=>'bg-gray-100','em_andamento'=>'bg-yellow-100 text-yellow-700','concluida'=>'bg-green-100 text-green-700'];foreach($lanes as $key=>$lane){$board.='<div class="bg-white border rounded-xl p-4"><div class="flex justify-between items-center mb-4"><h3 class="font-bold text-lg">'.$names[$key].'</h3><span class="'.$badges[$key].' px-3 rounded-full text-sm">'.count($lane).'</span></div><div class="space-y-3">';foreach($lane as $m)$board.=goal_card_compact($m,$admin);if(!$lane)$board.='<p class="text-sm text-gray-400">Nenhuma meta nesta coluna.</p>';$board.='</div>';if($admin&&$key==='a_fazer')$board.='<a href="#gerenciar-metas" class="block text-center border border-dashed rounded-lg p-3 mt-4 text-sm text-gray-500">+ Adicionar nova meta</a>';$board.='</div>';}$board.='</div>';
